INSERT INTO videos (slug,title,source_url,embed_url,media_type,r2_key,primary_category,subcategory,description,review_text,seo_title,seo_description,seo_tags,thumbnail_url,featured,trending,published)
SELECT draft.slug,draft.title,draft.source_url,draft.embed_url,draft.media_type,draft.r2_key,draft.primary_category,draft.subcategory,draft.description,draft.review_text,draft.seo_title,draft.seo_description,draft.seo_tags,draft.thumbnail_url,draft.featured,draft.trending,draft.published
FROM draft
WHERE NOT EXISTS (
 SELECT 1 FROM videos existing
 WHERE existing.source_url = draft.source_url OR existing.slug = draft.slug
);
